import{_ as r,I as a,o,c as i,j as t,a as n,J as h,a6 as d}from"./chunks/framework.9ylqSDY5.js";const w=JSON.parse('{"title":"Night Scheduler","description":"","frontmatter":{"title":"Night Scheduler","visibility":"public","audience":"astronomer","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/observing/night-scheduler.md","filePath":"guides/observing/night-scheduler.md"}'),l={name:"guides/observing/night-scheduler.md"};function g(u,e,p,c,f,m){const s=a("ToolShot");return o(),i("div",null,[e[0]||(e[0]=t("h1",{id:"night-scheduler",tabindex:"-1"},[n("Night Scheduler "),t("a",{class:"header-anchor",href:"#night-scheduler","aria-label":"Permalink to “Night Scheduler”"},"​")],-1)),e[1]||(e[1]=t("p",null,[t("strong",null,"Describe the night, press Run, read it in the morning."),n(" The Night Scheduler runs a sequence of steps, from opening the dome to closing it.")],-1)),h(s,{tool:"night-scheduler"}),e[2]||(e[2]=d('<h2 id="what-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to “What it is for”">​</a></h2><ul><li>Automate an entire night on one setup.</li><li>See the night before it happens: which target when, how high, and how much of the dark time is used.</li><li>Follow the night live, and step in when needed.</li></ul><h2 id="sequences-steps-tasks" tabindex="-1">Sequences, steps, tasks <a class="header-anchor" href="#sequences-steps-tasks" aria-label="Permalink to “Sequences, steps, tasks”">​</a></h2><p>A <strong>sequence</strong> is one night of one setup. It is made of <strong>steps</strong>, and each step of <strong>tasks</strong> that run one after the other or in parallel. An observation step starts with a pointing, followed by filters and their exposures: one step can go through L, R, G and B on the same target.</p><h2 id="build-a-night" tabindex="-1">Build a night <a class="header-anchor" href="#build-a-night" aria-label="Permalink to “Build a night”">​</a></h2><ol><li><strong>Create</strong> tonight&#39;s sequence, plan another night, or duplicate a sequence onto a new night.</li><li><strong>Open and close</strong>: drag <strong>Start of Night</strong> and <strong>End of Night</strong> from the Templates tab. Templates name kinds of equipment, and are bound to those of your setup when dropped.</li><li><strong>Add targets</strong>: drag them from the Targets tab, for <strong>One pass</strong> or <strong>Until dawn</strong>.</li><li><strong>Edit the steps</strong>: pointing by plain slew or by plate solving, filters, exposures, and what to do on error.</li><li><strong>Set the start</strong>: astronomical or nautical dusk, sunset, or a fixed time, with an offset.</li><li><strong>Check the plan</strong> on the night view: the steps are drawn over the airmass curves.</li></ol><h3 id="repeating-a-step" tabindex="-1">Repeating a step <a class="header-anchor" href="#repeating-a-step" aria-label="Permalink to “Repeating a step”">​</a></h3><p>A step can loop until dawn, until a given time, or for a number of passes. Each pass repeats everything but the pointing. With several conditions, the loop goes on while all of them hold.</p><h3 id="focus-and-dithering" tabindex="-1">Focus and dithering <a class="header-anchor" href="#focus-and-dithering" aria-label="Permalink to “Focus and dithering”">​</a></h3><p>Press <strong>Configure...</strong> in the header of the sequence, and set the autofocus and dither rules for the setup or for this sequence only. Autofocus runs when the temperature has drifted or enough time has passed; dithering, after a number of light frames. Each firing is recorded with its reason.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Run...</strong></td><td>Starts the sequence</td></tr><tr><td><strong>Pause</strong></td><td>Pauses once the current task is over. Resume goes on from the next one</td></tr><tr><td><strong>Stop</strong></td><td>Stops now, cancelling the current task. Edit the steps not reached yet, then Resume from where it stopped</td></tr><tr><td><strong>Abort...</strong></td><td>Ends the sequence for good</td></tr></tbody></table><p>The Activity tab follows the night: safety, meridian flips, and the autofocus and dither triggers.</p><h2 id="when-something-interrupts" tabindex="-1">When something interrupts <a class="header-anchor" href="#when-something-interrupts" aria-label="Permalink to “When something interrupts”">​</a></h2><ul><li><strong>Conditions turn bad.</strong> The sequence is interrupted and the safety procedure runs. The observatory stays closed until you reopen it: safety never reopens on its own. See <a href="./safety-configuration">Safety Configuration</a>.</li><li><strong>A transient takes the telescope.</strong> The sequence stops for the observation series and resumes on its own afterwards. If it cannot, the reason is shown. See <a href="./too-policies">Targets of Opportunity</a>.</li></ul><h2 id="afterwards" tabindex="-1">Afterwards <a class="header-anchor" href="#afterwards" aria-label="Permalink to “Afterwards”">​</a></h2><p>A sequence that ran is a record and becomes read-only: duplicate it to run it again. Its header links to the night log and the dataset. A past sequence that never ran is still editable.</p>',17))])}const k=r(l,[["render",g]]);export{w as __pageData,k as default};
